ARCHIVOS = json.loads('{".gitignore": "venv/\\n.venv/\\n__pycache__/\\ninstance/\\n.env\\n", "README.md": "# Ficha clínica · Python / Flask / MVC\\n\\nPrototipo educativo local. Usar únicamente datos ficticios. No incluye autenticación ni permisos; registrar un profesional no crea una cuenta de acceso.\\n\\n## Ejecutar en Visual Studio Code\\n1. Descomprime el proyecto y abre la carpeta `ficha_clinica` en VS Code.\\n2. Instala Python 3.10 o superior y la extensión Python de VS Code.\\n3. Abre Terminal → Nueva terminal.\\n\\n### Windows (PowerShell)\\n```powershell\\npy -m venv venv\\n.\\\\venv\\\\Scripts\\\\python.exe -m pip install -r requirements.txt\\n.\\\\venv\\\\Scripts\\\\python.exe run.py\\n```\\nNo es necesario activar el entorno ni modificar la política de PowerShell.\\n\\n### Ubuntu / Linux\\n```bash\\npython3 -m venv venv\\nvenv/bin/python -m pip install -r requirements.txt\\nvenv/bin/python run.py\\n```\\nSi Ubuntu no tiene venv: `sudo apt install python3-venv`.\\n\\n4. Abre http://127.0.0.1:5000 en el navegador del mismo equipo donde ejecutaste Python.\\n5. Ya hay seis profesionales de ejemplo. Registra un paciente, presiona Ver ficha y guarda una atención.\\n6. Detén el servidor con Ctrl+C. Los registros permanecen al reiniciar.\\n\\nSi trabajas por SSH, reenvía el puerto 5000 en la pestaña Puertos de VS Code y abre la dirección local reenviada.\\n\\n## Funciones\\n- Crear, buscar y listar pacientes.\\n- Registrar profesionales con cargo y especialidad.\\n- Seis profesionales ficticios se agregan una sola vez al iniciar.\\n- Registrar varias atenciones de distintos profesionales para un mismo paciente.\\n- Consultar la ficha con historial ordenado por fecha.\\n- Eliminar pacientes mediante confirmación explícita (incluye sus atenciones).\\n- Evitar documentos repetidos, fechas futuras y profesionales inexistentes.\\n\\nEl documento se normaliza quitando puntos y espacios y convirtiéndolo a mayúsculas. No valida el dígito verificador del RUT. No incluye edición de pacientes en esta versión.\\n\\n## Organización MVC\\n- Modelo: `app/models/`: base de datos y consultas parametrizadas.\\n- Vista: `app/templates/` y `app/static/`: páginas HTML y diseño.\\n- Controlador: `app/controllers/clinica_controller.py`: rutas, validaciones y coordinación.\\n- `app/__init__.py`: crea y configura la aplicación.\\n- `run.py`: punto de entrada.\\n\\nFlask utiliza Jinja para las plantillas. Las carpetas organizan el proyecto según MVC; no se necesita un framework adicional.\\n\\n## Base de datos\\nSQLite crea automáticamente `instance/clinica.sqlite` en la primera ejecución.\\n\\n`pacientes (1) → atenciones (muchas) ← (1) profesionales`\\n\\nCada atención guarda paciente, profesional, fecha, motivo, diagnóstico y tratamiento. La relación paciente-profesional es de muchos a muchos a través de atenciones. Un paciente sin atenciones también puede existir.\\n\\n## Pruebas\\n```bash\\npython -m unittest discover -s tests -v\\n```\\nEn Windows usa `venv\\\\Scripts\\\\python.exe`; en Linux `venv/bin/python` en lugar de `python`.\\n\\n## Alcance\\nEl servidor escucha solo en el equipo local y no usa modo debug. Incluye protección CSRF y consultas parametrizadas. Para datos clínicos reales se requiere una versión con autenticación, permisos por rol, auditoría, HTTPS, copias de seguridad y políticas de conservación del historial. La eliminación definitiva implementada aquí es para el prototipo; su comportamiento debe definirse antes del uso clínico.\\n\\nDocumentación oficial: https://flask.palletsprojects.com/en/stable/quickstart/\\n\\n## Actualizar una instalación anterior en Ubuntu\\nDetén el servidor con Ctrl+C. Copia `actualizar_ficha.py` en tu carpeta remota `~/ficha_clinica` usando el explorador de VS Code (SSH), y ejecuta:\\n```bash\\ncd ~/ficha_clinica\\npython3 actualizar_ficha.py\\nvenv/bin/python -m pip install -r requirements.txt\\nvenv/bin/python run.py\\n```\\nEl actualizador hace una copia de seguridad del código y de la base de datos en una carpeta `respaldo_...`. Actualiza código y plantillas, sin sustituir `instance/clinica.sqlite` ni el entorno virtual. Al iniciar Flask se agrega la columna cargo a la base antigua sin borrar registros.\\n\\nSi Ver ficha sigue mostrando un error, comprueba que la dirección cambió a `/pacientes/NUMERO` y lee el mensaje de la terminal. Guarda todos los archivos y reinicia el proceso correcto. No se ha inspeccionado el código instalado en tu máquina: esta distribución contiene todos los archivos completos para evitar plantillas vacías o faltantes.\\n", "run.py": "from app import create_app\\n\\napp = create_app()\\n\\nif __name__ == \\"__main__\\":\\n    app.run(host=\\"127.0.0.1\\", port=5000, debug=False)\\n", "requirements.txt": "Flask==3.1.3\\n", "app/__init__.py": "import os\\nimport secrets\\nfrom pathlib import Path\\nfrom flask import Flask, session, request, abort, render_template\\nfrom .models.database import init_db\\n\\ndef create_app(test_config=None):\\n    app = Flask(__name__, instance_relative_config=True)\\n    app.config.update(SECRET_KEY=os.environ.get(\'SECRET_KEY\') or secrets.token_hex(32),\\n                      DATABASE=str(Path(app.instance_path) / \'clinica.sqlite\'),\\n                      SESSION_COOKIE_HTTPONLY=True, SESSION_COOKIE_SAMESITE=\'Lax\',\\n                      MAX_CONTENT_LENGTH=1024*1024)\\n    if test_config:\\n        app.config.update(test_config)\\n    Path(app.instance_path).mkdir(parents=True, exist_ok=True)\\n    init_db(app)\\n    @app.before_request\\n    def proteger_formularios():\\n        session.setdefault(\'csrf\', secrets.token_urlsafe(32))\\n        if request.method == \'POST\':\\n            if not secrets.compare_digest(session[\'csrf\'], request.form.get(\'csrf\', \'\')):\\n                abort(400, description=\'Formulario vencido o inválido. Recarga la página.\')\\n    from .controllers.clinica_controller import bp\\n    app.register_blueprint(bp)\\n    @app.errorhandler(404)\\n    def no_encontrado(error):\\n        return render_template(\'error.html\', titulo=\'Ficha no encontrada\', mensaje=\'El paciente no existe o fue eliminado.\'), 404\\n    @app.errorhandler(500)\\n    def error_interno(error):\\n        return render_template(\'error.html\', titulo=\'No se pudo abrir esta página\', mensaje=\'Revisa el error en la terminal donde ejecutaste run.py.\'), 500\\n    return app\\n", "tests/test_actualizacion.py": "import sqlite3\\nimport tempfile\\nimport unittest\\nfrom pathlib import Path\\nfrom app import create_app\\nfrom app.models.database import get_db\\n\\nclass ActualizacionTest(unittest.TestCase):\\n    def test_migracion_preserva_datos_y_demo_no_se_duplica(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            dbpath = str(Path(tmp)/\'vieja.sqlite\')\\n            db = sqlite3.connect(dbpath)\\n            db.executescript(\\"\\"\\"\\n                CREATE TABLE pacientes(id INTEGER PRIMARY KEY,documento TEXT NOT NULL UNIQUE,nombre TEXT NOT NULL,nacimiento TEXT NOT NULL,telefono TEXT NOT NULL DEFAULT \'\',correo TEXT NOT NULL DEFAULT \'\');\\n                CREATE TABLE profesionales(id INTEGER PRIMARY KEY,nombre TEXT NOT NULL,especialidad TEXT NOT NULL);\\n                CREATE TABLE atenciones(id INTEGER PRIMARY KEY,paciente_id INTEGER NOT NULL REFERENCES pacientes(id) ON DELETE CASCADE,profesional_id INTEGER NOT NULL REFERENCES profesionales(id),fecha TEXT NOT NULL,motivo TEXT NOT NULL,diagnostico TEXT NOT NULL,tratamiento TEXT NOT NULL);\\n                INSERT INTO pacientes VALUES(1,\'FICTICIO\',\'Paciente anterior\',\'2000-01-01\',\'\',\'\');\\n                INSERT INTO profesionales VALUES(1,\'Profesional anterior\',\'Medicina\');\\n                INSERT INTO atenciones VALUES(1,1,1,\'2020-01-01\',\'Control\',\'Prueba\',\'Prueba\');\\n            \\"\\"\\")\\n            db.commit(); db.close()\\n            for _ in range(2):\\n                app = create_app({\'TESTING\':True,\'DATABASE\':dbpath,\'SECRET_KEY\':\'test\'})\\n                client=app.test_client()\\n                self.assertEqual(client.get(\'/\').status_code,200)\\n                r=client.get(\'/pacientes/1\')\\n                self.assertEqual(r.status_code,200)\\n                self.assertIn(b\'Paciente anterior\',r.data)\\n                self.assertIn(b\'Profesional anterior\',r.data)\\n                self.assertIn(b\'Registrar atenci\',r.data)\\n                self.assertEqual(client.get(\'/profesionales\').status_code,200)\\n                with app.app_context():\\n                    self.assertEqual(get_db().execute(\'SELECT COUNT(*) FROM profesionales\').fetchone()[0],7)\\n                    self.assertEqual(get_db().execute(\'SELECT COUNT(*) FROM atenciones\').fetchone()[0],1)\\n", "tests/test_clinica.py": "import tempfile\\nimport unittest\\nfrom pathlib import Path\\nfrom app import create_app\\nfrom app.models.database import get_db\\n\\nclass ClinicaTest(unittest.TestCase):\\n    def setUp(self):\\n        self.tmp = tempfile.TemporaryDirectory()\\n        self.app = create_app({\'TESTING\':True, \'CARGAR_DEMO\':False, \'SECRET_KEY\':\'test\', \'DATABASE\':str(Path(self.tmp.name)/\'test.sqlite\')})\\n        self.client = self.app.test_client()\\n        self.client.get(\'/\')\\n        with self.client.session_transaction() as s:\\n            self.csrf = s[\'csrf\']\\n    def tearDown(self):\\n        self.tmp.cleanup()\\n    def post(self,url,**datos):\\n        return self.client.post(url,data=dict(csrf=self.csrf,**datos),follow_redirects=True)\\n    def paciente(self):\\n        return self.post(\'/pacientes/nuevo\',documento=\'TEST-1\',nombre=\'Paciente ficticio\',nacimiento=\'2000-01-01\')\\n    def test_historial_distintos_profesionales_y_eliminacion(self):\\n        self.post(\'/profesionales\',nombre=\'Profesional A\',especialidad=\'Medicina\',cargo=\'Médico\')\\n        self.post(\'/profesionales\',nombre=\'Profesional B\',especialidad=\'Enfermería\',cargo=\'Enfermero\')\\n        self.assertEqual(self.paciente().status_code,200)\\n        for id in (1,2):\\n            r=self.post(\'/pacientes/1/atenciones\',profesional_id=str(id),fecha=\'2020-01-01\',motivo=\'Control\',diagnostico=\'Evaluación ficticia\',tratamiento=\'Indicaciones ficticias\')\\n            self.assertEqual(r.status_code,200)\\n        r=self.client.get(\'/pacientes/1\')\\n        self.assertIn(b\'Profesional A\',r.data)\\n        self.assertIn(b\'Profesional B\',r.data)\\n        with self.app.app_context():\\n            self.assertEqual(get_db().execute(\'SELECT COUNT(*) FROM atenciones\').fetchone()[0],2)\\n        self.post(\'/pacientes/1/eliminar\',confirmar=\'incorrecto\')\\n        self.assertEqual(self.client.get(\'/pacientes/1\').status_code,200)\\n        self.post(\'/pacientes/1/eliminar\',confirmar=\'ELIMINAR\')\\n        self.assertEqual(self.client.get(\'/pacientes/1\').status_code,404)\\n        with self.app.app_context():\\n            self.assertEqual(get_db().execute(\'SELECT COUNT(*) FROM atenciones\').fetchone()[0],0)\\n    def test_validaciones_y_csrf(self):\\n        self.paciente()\\n        self.paciente()\\n        self.post(\'/pacientes/nuevo\',documento=\'TEST-2\',nombre=\'Futuro\',nacimiento=\'2999-01-01\')\\n        self.post(\'/pacientes/1/atenciones\',profesional_id=\'999\',fecha=\'2020-01-01\',motivo=\'X\',diagnostico=\'X\',tratamiento=\'X\')\\n        with self.app.app_context():\\n            self.assertEqual(get_db().execute(\'SELECT COUNT(*) FROM pacientes\').fetchone()[0],1)\\n            self.assertEqual(get_db().execute(\'SELECT COUNT(*) FROM atenciones\').fetchone()[0],0)\\n        self.assertEqual(self.client.post(\'/pacientes/1/eliminar\',data={\'confirmar\':\'ELIMINAR\'}).status_code,400)\\n        self.assertEqual(self.client.get(\'/pacientes/999\').status_code,404)\\n\\nif __name__ == \'__main__\':\\n    unittest.main()\\n", "app/static/style.css": "*{box-sizing:border-box}body{margin:0;background:#f2f6f9;color:#233443;font:16px/1.6 system-ui,sans-serif}header{background:#124e61;color:white;padding:20px 6%;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}nav a{color:white;margin-right:20px}main{max-width:1000px;margin:30px auto;padding:0 20px}h1,h2{color:#124e61}form,article,section{background:white;padding:24px;border:1px solid #dce5e9;border-radius:12px;margin:20px 0}label{display:block;margin:12px 0}input,select,textarea{display:block;width:100%;padding:10px;border:1px solid #a5b7bf;border-radius:6px;font:inherit}textarea{min-height:100px}button,.boton{display:inline-block;background:#126b72;color:white;border:0;padding:10px 18px;border-radius:6px;cursor:pointer;text-decoration:none;font:inherit}.peligro{color:#9c2039}button.peligro{background:#9c2039;color:white}.mensaje{background:#dff1eb;padding:12px}.aviso{font-size:14px;color:#61737d}table{width:100%;border-collapse:collapse;background:white}td,th{text-align:left;padding:14px;border-bottom:1px solid #dce5e9}.tabla{overflow:auto}article p{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#126b72}input:focus,select:focus,textarea:focus{outline:2px solid #126b72}", "app/controllers/clinica_controller.py": "import sqlite3\\nfrom datetime import date\\nfrom flask import Blueprint, render_template, request, redirect, url_for, flash, abort\\nfrom ..models.clinica_model import PacienteModel, ProfesionalModel, AtencionModel\\n\\nbp = Blueprint(\'clinica\', __name__)\\n\\ndef campo(nombre, maximo=200, obligatorio=True):\\n    valor = request.form.get(nombre, \'\').strip()\\n    if (obligatorio and not valor) or len(valor) > maximo:\\n        raise ValueError(f\'Revisa el campo {nombre}: obligatorio y máximo {maximo} caracteres.\')\\n    return valor\\n\\ndef fecha(nombre):\\n    try:\\n        valor = date.fromisoformat(campo(nombre, 10))\\n    except ValueError:\\n        raise ValueError(\'Ingresa una fecha válida.\')\\n    if valor > date.today():\\n        raise ValueError(\'La fecha no puede ser futura.\')\\n    return valor.isoformat()\\n\\n@bp.get(\'/\')\\ndef index():\\n    q = request.args.get(\'q\', \'\').strip()[:200]\\n    return render_template(\'pacientes.html\', pacientes=PacienteModel.listar(q), q=q)\\n\\n@bp.route(\'/pacientes/nuevo\', methods=[\'GET\',\'POST\'])\\ndef nuevo_paciente():\\n    if request.method == \'POST\':\\n        try:\\n            documento = campo(\'documento\', 40).replace(\'.\', \'\').replace(\' \', \'\').upper()\\n            if not documento:\\n                raise ValueError(\'Ingresa un documento válido.\')\\n            id = PacienteModel.crear((documento, campo(\'nombre\'), fecha(\'nacimiento\'),\\n                                     campo(\'telefono\',40,False), campo(\'correo\',200,False)))\\n            flash(\'Paciente registrado correctamente.\')\\n            return redirect(url_for(\'clinica.ficha\', id=id))\\n        except sqlite3.IntegrityError:\\n            flash(\'Ya existe un paciente con ese documento.\')\\n        except ValueError as e:\\n            flash(str(e))\\n    return render_template(\'nuevo_paciente.html\')\\n\\n@bp.get(\'/pacientes/<int:id>\')\\ndef ficha(id):\\n    paciente = PacienteModel.obtener(id)\\n    if paciente is None:\\n        abort(404)\\n    return render_template(\'ficha.html\', paciente=paciente, atenciones=AtencionModel.listar(id),\\n                           profesionales=ProfesionalModel.listar(), hoy=date.today().isoformat())\\n\\n@bp.post(\'/pacientes/<int:id>/atenciones\')\\ndef nueva_atencion(id):\\n    if PacienteModel.obtener(id) is None:\\n        abort(404)\\n    try:\\n        profesional = int(campo(\'profesional_id\',20))\\n        if ProfesionalModel.obtener(profesional) is None:\\n            raise ValueError(\'Selecciona un profesional registrado.\')\\n        AtencionModel.crear((id, profesional, fecha(\'fecha\'), campo(\'motivo\',2000),\\n                            campo(\'diagnostico\',4000), campo(\'tratamiento\',4000)))\\n        flash(\'Atención registrada.\')\\n    except ValueError as e:\\n        flash(str(e))\\n        return ficha(id)\\n    return redirect(url_for(\'clinica.ficha\', id=id))\\n\\n@bp.route(\'/pacientes/<int:id>/eliminar\', methods=[\'GET\',\'POST\'])\\ndef eliminar(id):\\n    paciente = PacienteModel.obtener(id)\\n    if paciente is None:\\n        abort(404)\\n    if request.method == \'POST\':\\n        if request.form.get(\'confirmar\') != \'ELIMINAR\':\\n            flash(\'Escribe ELIMINAR para confirmar.\')\\n        else:\\n            PacienteModel.eliminar(id)\\n            flash(\'Paciente y sus atenciones eliminados.\')\\n            return redirect(url_for(\'clinica.index\'))\\n    return render_template(\'eliminar.html\', paciente=paciente)\\n\\n@bp.route(\'/profesionales\', methods=[\'GET\',\'POST\'])\\ndef profesionales():\\n    if request.method == \'POST\':\\n        try:\\n            ProfesionalModel.crear(campo(\'nombre\'), campo(\'especialidad\',100), campo(\'cargo\',100))\\n            flash(\'Profesional registrado.\')\\n            return redirect(url_for(\'clinica.profesionales\'))\\n        except ValueError as e:\\n            flash(str(e))\\n    return render_template(\'profesionales.html\', profesionales=ProfesionalModel.listar())\\n", "app/controllers/__init__.py": "", "app/templates/ficha.html": "{% extends \'base.html\' %}{% block content %}<a href=\\"{{ url_for(\'clinica.index\') }}\\">← Volver a pacientes</a><h1>Ficha de {{ paciente.nombre }}</h1><section><p><strong>Documento:</strong> {{ paciente.documento }} · <strong>Nacimiento:</strong> {{ paciente.nacimiento }}</p><p>Teléfono: {{ paciente.telefono or \'Sin registrar\' }} · Correo: {{ paciente.correo or \'Sin registrar\' }}</p></section><h2>Registrar atención</h2>{% if profesionales %}<form method=\\"post\\" action=\\"{{ url_for(\'clinica.nueva_atencion\',id=paciente.id) }}\\"><input type=\\"hidden\\" name=\\"csrf\\" value=\\"{{ session.csrf }}\\"><label>Profesional<select name=\\"profesional_id\\" required><option value=\\"\\">Selecciona un profesional</option>{% for p in profesionales %}<option value=\\"{{ p.id }}\\" {% if request.form.get(\'profesional_id\') == p.id|string %}selected{% endif %}>{{ p.nombre }} — {{ p.cargo }} / {{ p.especialidad }}</option>{% endfor %}</select></label><label>Fecha<input type=\\"date\\" name=\\"fecha\\" value=\\"{{ request.form.get(\'fecha\',hoy) }}\\" max=\\"{{ hoy }}\\" required></label>{% for name,label,length in [(\'motivo\',\'Motivo de consulta\',2000),(\'diagnostico\',\'Diagnóstico / evaluación\',4000),(\'tratamiento\',\'Tratamiento / indicaciones\',4000)] %}<label>{{ label }}<textarea name=\\"{{ name }}\\" maxlength=\\"{{ length }}\\" required>{{ request.form.get(name,\'\') }}</textarea></label>{% endfor %}<button>Guardar atención</button></form>{% else %}<p>Primero <a href=\\"{{ url_for(\'clinica.profesionales\') }}\\">registra un profesional</a>.</p>{% endif %}<h2>Historial clínico</h2>{% for a in atenciones %}<article><h3>{{ a.fecha }} · {{ a.profesional }}</h3><p>{{ a.cargo }} · {{ a.especialidad }}</p><p><strong>Motivo:</strong> {{ a.motivo }}</p><p><strong>Diagnóstico:</strong> {{ a.diagnostico }}</p><p><strong>Indicaciones:</strong> {{ a.tratamiento }}</p></article>{% else %}<p>Sin atenciones registradas.</p>{% endfor %}<a class=\\"peligro\\" href=\\"{{ url_for(\'clinica.eliminar\',id=paciente.id) }}\\">Eliminar paciente</a>{% endblock %}", "app/templates/nuevo_paciente.html": "{% extends \'base.html\' %}{% block content %}<h1>Registrar paciente</h1><form method=\\"post\\"><input type=\\"hidden\\" name=\\"csrf\\" value=\\"{{ session.csrf }}\\">{% for name,label,length in [(\'documento\',\'RUT u otro documento\',40),(\'nombre\',\'Nombre completo\',200),(\'telefono\',\'Teléfono\',40),(\'correo\',\'Correo\',200)] %}<label>{{ label }}<input name=\\"{{ name }}\\" maxlength=\\"{{ length }}\\" value=\\"{{ request.form.get(name,\'\') }}\\" {% if name in [\'documento\',\'nombre\'] %}required{% endif %} {% if name == \'correo\' %}type=\\"email\\"{% endif %}></label>{% endfor %}<label>Fecha de nacimiento<input type=\\"date\\" name=\\"nacimiento\\" value=\\"{{ request.form.get(\'nacimiento\',\'\') }}\\" required></label><button>Guardar paciente</button></form>{% endblock %}", "app/templates/error.html": "{% extends \'base.html\' %}{% block content %}<h1>{{ titulo }}</h1><p>{{ mensaje }}</p><a class=\\"boton\\" href=\\"{{ url_for(\'clinica.index\') }}\\">Volver a pacientes</a>{% endblock %}", "app/templates/pacientes.html": "{% extends \'base.html\' %}{% block content %}<h1>Pacientes</h1><a class=\\"boton\\" href=\\"{{ url_for(\'clinica.nuevo_paciente\') }}\\">Registrar paciente</a><form method=\\"get\\"><label>Buscar por nombre o documento<input name=\\"q\\" value=\\"{{ q }}\\"></label><button>Buscar</button></form><div class=\\"tabla\\"><table><thead><tr><th>Documento</th><th>Nombre</th><th>Ficha</th></tr></thead><tbody>{% for p in pacientes %}<tr><td>{{ p.documento }}</td><td>{{ p.nombre }}</td><td><a class=\\"boton\\" href=\\"{{ url_for(\'clinica.ficha\', id=p.id) }}\\">Ver ficha</a></td></tr>{% else %}<tr><td colspan=\\"3\\">No hay pacientes para mostrar.</td></tr>{% endfor %}</tbody></table></div>{% endblock %}", "app/templates/eliminar.html": "{% extends \'base.html\' %}{% block content %}<h1>Eliminar paciente</h1><p>Se eliminará a <strong>{{ paciente.nombre }}</strong> y todas sus atenciones. Esta acción no se puede deshacer.</p><form method=\\"post\\"><input type=\\"hidden\\" name=\\"csrf\\" value=\\"{{ session.csrf }}\\"><label>Escribe ELIMINAR para confirmar<input name=\\"confirmar\\" required autocomplete=\\"off\\"></label><button class=\\"peligro\\">Eliminar definitivamente</button> <a href=\\"{{ url_for(\'clinica.ficha\',id=paciente.id) }}\\">Cancelar</a></form>{% endblock %}", "app/templates/base.html": "<!doctype html>\\n<html lang=\\"es\\"><head><meta charset=\\"utf-8\\"><meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\"><title>Ficha clínica</title><link rel=\\"stylesheet\\" href=\\"{{ url_for(\'static\', filename=\'style.css\') }}\\"></head>\\n<body><header><strong>Ficha clínica</strong><nav><a href=\\"{{ url_for(\'clinica.index\') }}\\">Pacientes</a><a href=\\"{{ url_for(\'clinica.profesionales\') }}\\">Profesionales</a></nav></header><main><p class=\\"aviso\\">Prototipo local · Utiliza solamente datos ficticios</p>{% for mensaje in get_flashed_messages() %}<p class=\\"mensaje\\" role=\\"status\\">{{ mensaje }}</p>{% endfor %}{% block content %}{% endblock %}</main></body></html>", "app/templates/profesionales.html": "{% extends \'base.html\' %}{% block content %}<h1>Profesionales</h1><p>Los profesionales marcados “demo” son ficticios y permiten probar las atenciones.</p><form method=\\"post\\"><input type=\\"hidden\\" name=\\"csrf\\" value=\\"{{ session.csrf }}\\"><label>Nombre completo<input name=\\"nombre\\" maxlength=\\"200\\" required></label><label>Cargo<input name=\\"cargo\\" maxlength=\\"100\\" placeholder=\\"Médico, enfermera, psicólogo…\\" required></label><label>Especialidad<input name=\\"especialidad\\" maxlength=\\"100\\" placeholder=\\"Medicina general, enfermería…\\" required></label><button>Registrar profesional</button></form><div class=\\"tabla\\"><table><thead><tr><th>Nombre</th><th>Cargo</th><th>Especialidad</th></tr></thead><tbody>{% for p in profesionales %}<tr><td>{{ p.nombre }}</td><td>{{ p.cargo }}</td><td>{{ p.especialidad }}</td></tr>{% else %}<tr><td colspan=\\"3\\">Sin profesionales.</td></tr>{% endfor %}</tbody></table></div>{% endblock %}", "app/models/database.py": "import sqlite3\\nfrom flask import current_app, g\\n\\ndef get_db():\\n    if \'db\' not in g:\\n        g.db = sqlite3.connect(current_app.config[\'DATABASE\'])\\n        g.db.row_factory = sqlite3.Row\\n        g.db.execute(\'PRAGMA foreign_keys = ON\')\\n    return g.db\\n\\ndef init_db(app):\\n    @app.teardown_appcontext\\n    def close_db(error=None):\\n        db = g.pop(\'db\', None)\\n        if db is not None:\\n            db.close()\\n    with app.app_context():\\n        get_db().executescript(\\"\\"\\"\\n        CREATE TABLE IF NOT EXISTS pacientes (\\n            id INTEGER PRIMARY KEY, documento TEXT NOT NULL UNIQUE,\\n            nombre TEXT NOT NULL, nacimiento TEXT NOT NULL,\\n            telefono TEXT NOT NULL DEFAULT \'\', correo TEXT NOT NULL DEFAULT \'\');\\n        CREATE TABLE IF NOT EXISTS profesionales (\\n            id INTEGER PRIMARY KEY, nombre TEXT NOT NULL, especialidad TEXT NOT NULL);\\n        CREATE TABLE IF NOT EXISTS atenciones (\\n            id INTEGER PRIMARY KEY,\\n            paciente_id INTEGER NOT NULL REFERENCES pacientes(id) ON DELETE CASCADE,\\n            profesional_id INTEGER NOT NULL REFERENCES profesionales(id),\\n            fecha TEXT NOT NULL, motivo TEXT NOT NULL,\\n            diagnostico TEXT NOT NULL, tratamiento TEXT NOT NULL);\\n        CREATE INDEX IF NOT EXISTS idx_atenciones_paciente ON atenciones(paciente_id);\\n        \\"\\"\\")\\n\\n        db = get_db()\\n        columnas = {r[\'name\'] for r in db.execute(\'PRAGMA table_info(profesionales)\')}\\n        if \'cargo\' not in columnas:\\n            db.execute(\\"ALTER TABLE profesionales ADD COLUMN cargo TEXT NOT NULL DEFAULT \'Profesional de salud\'\\")\\n        db.execute(\'CREATE TABLE IF NOT EXISTS configuracion (clave TEXT PRIMARY KEY, valor TEXT NOT NULL)\')\\n        if app.config.get(\'CARGAR_DEMO\', True):\\n            with db:\\n                if not db.execute(\\"SELECT 1 FROM configuracion WHERE clave=\'profesionales_demo_v1\'\\").fetchone():\\n                    ejemplos = [\\n                        (\'Ana Pérez (demo)\', \'Medicina general\', \'Médica\'),\\n                        (\'Luis Soto (demo)\', \'Enfermería\', \'Enfermero\'),\\n                        (\'Camila Rojas (demo)\', \'Psicología\', \'Psicóloga\'),\\n                        (\'Diego Muñoz (demo)\', \'Kinesiología\', \'Kinesiólogo\'),\\n                        (\'Valentina Díaz (demo)\', \'Nutrición\', \'Nutricionista\'),\\n                        (\'Carolina Torres (demo)\', \'Obstetricia\', \'Matrona\')]\\n                    for nombre, especialidad, cargo in ejemplos:\\n                        if not db.execute(\'SELECT 1 FROM profesionales WHERE nombre=? AND especialidad=?\', (nombre, especialidad)).fetchone():\\n                            db.execute(\'INSERT INTO profesionales(nombre,especialidad,cargo) VALUES(?,?,?)\', (nombre,especialidad,cargo))\\n                    db.execute(\\"INSERT INTO configuracion(clave,valor) VALUES(\'profesionales_demo_v1\',\'1\')\\")\\n        db.commit()\\n", "app/models/clinica_model.py": "from .database import get_db\\n\\nclass PacienteModel:\\n    @staticmethod\\n    def listar(busqueda=\'\'):\\n        return get_db().execute(\'SELECT * FROM pacientes WHERE nombre LIKE ? OR documento LIKE ? ORDER BY nombre\',\\n                                (\'%\'+busqueda+\'%\', \'%\'+busqueda+\'%\')).fetchall()\\n    @staticmethod\\n    def obtener(id):\\n        return get_db().execute(\'SELECT * FROM pacientes WHERE id=?\', (id,)).fetchone()\\n    @staticmethod\\n    def crear(datos):\\n        db = get_db()\\n        with db:\\n            c = db.execute(\'INSERT INTO pacientes(documento,nombre,nacimiento,telefono,correo) VALUES(?,?,?,?,?)\', datos)\\n        return c.lastrowid\\n    @staticmethod\\n    def eliminar(id):\\n        db = get_db()\\n        with db:\\n            db.execute(\'DELETE FROM pacientes WHERE id=?\', (id,))\\n\\nclass ProfesionalModel:\\n    @staticmethod\\n    def listar():\\n        return get_db().execute(\'SELECT * FROM profesionales ORDER BY nombre\').fetchall()\\n    @staticmethod\\n    def obtener(id):\\n        return get_db().execute(\'SELECT * FROM profesionales WHERE id=?\', (id,)).fetchone()\\n    @staticmethod\\n    def crear(nombre, especialidad, cargo):\\n        db = get_db()\\n        with db:\\n            db.execute(\'INSERT INTO profesionales(nombre,especialidad,cargo) VALUES(?,?,?)\', (nombre,especialidad,cargo))\\n\\nclass AtencionModel:\\n    @staticmethod\\n    def listar(paciente_id):\\n        return get_db().execute(\\"\\"\\"SELECT a.*, p.nombre AS profesional, p.especialidad, p.cargo\\n            FROM atenciones a JOIN profesionales p ON p.id=a.profesional_id\\n            WHERE a.paciente_id=? ORDER BY a.fecha DESC, a.id DESC\\"\\"\\", (paciente_id,)).fetchall()\\n    @staticmethod\\n    def crear(datos):\\n        db = get_db()\\n        with db:\\n            db.execute(\'INSERT INTO atenciones(paciente_id,profesional_id,fecha,motivo,diagnostico,tratamiento) VALUES(?,?,?,?,?,?)\', datos)\\n", "app/models/__init__.py": ""}')

def main():
    destino = Path(__file__).resolve().parent
    backup = destino / ('respaldo_' + datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    backup.mkdir()
    # Respaldar todos los archivos que se van a reemplazar antes de escribir.
    for nombre in ARCHIVOS:
        f = destino / nombre
        if f.is_file():
            copia = backup / nombre
            copia.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, copia)
    original = destino / 'instance' / 'clinica.sqlite'
    if original.is_file():
        copia = backup / 'instance' / 'clinica.sqlite'
        copia.parent.mkdir(parents=True, exist_ok=True)
        with sqlite3.connect(str(original)) as origen, sqlite3.connect(str(copia)) as receptor:
            origen.backup(receptor)
    for nombre, contenido in ARCHIVOS.items():
        f = destino / nombre
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(contenido, encoding='utf-8')
    print('Aplicación actualizada correctamente en:', destino)
    print('Respaldo guardado en:', backup)
    print('La base de datos original y el entorno virtual se conservaron.')
    print('Ahora ejecuta:')
    print('venv/bin/python -m pip install -r requirements.txt')
    print('venv/bin/python run.py')

if __name__ == '__main__':
    main()
